  output_streamer #(.Y_ELEMS_FIXED(Y_ELEMS_FIXED)) u_out (.*);
  local_memories #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_mem (.*);

